#![cfg(feature = "tls")]
//! TLS (feature `tls`): a rustls-terminated listener in front of `FakeRedis`,
//! with a throw-away certificate generated by the `openssl` CLI (the test is
//! skipped with a notice when it is missing). The client trusts it through
//! `RedisConfig::tls_extra_roots_der`.

mod common;

use std::{path::PathBuf, process::Command, sync::Arc, time::Duration};

use futures_rustls::{
    TlsAcceptor,
    rustls::{
        ServerConfig,
        crypto::ring,
        pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer},
    },
};
use moonpool_core::TokioProviders;
use streaming_core::KvError;
use streaming_kv_redis::{FakeRedis, RedisConfig, RedisKv, testkit::conformance};
use tokio::net::TcpListener;
use tokio_util::compat::TokioAsyncReadCompatExt;

struct Cert {
    cert_der: Vec<u8>,
    key_der: Vec<u8>,
}

fn generate_cert() -> Option<Cert> {
    let dir: PathBuf = std::env::temp_dir().join(format!("kvredis-tls-{}-{}", std::process::id(), common::free_port()));
    std::fs::create_dir_all(&dir).ok()?;
    let p = |n: &str| dir.join(n).to_string_lossy().into_owned();
    let run = |args: &[&str]| {
        Command::new("openssl")
            .args(args)
            .output()
            .ok()
            .filter(|o| o.status.success())
    };
    run(&[
        "req",
        "-x509",
        "-newkey",
        "ec",
        "-pkeyopt",
        "ec_paramgen_curve:prime256v1",
        "-nodes",
        "-keyout",
        &p("key.pem"),
        "-out",
        &p("cert.pem"),
        "-days",
        "2",
        "-subj",
        "/CN=localhost",
        "-addext",
        "subjectAltName=DNS:localhost",
        "-addext",
        "basicConstraints=critical,CA:FALSE",
    ])?;
    run(&["x509", "-in", &p("cert.pem"), "-outform", "DER", "-out", &p("cert.der")])?;
    run(&[
        "pkcs8",
        "-topk8",
        "-nocrypt",
        "-in",
        &p("key.pem"),
        "-outform",
        "DER",
        "-out",
        &p("key.der"),
    ])?;
    let cert = Cert {
        cert_der: std::fs::read(p("cert.der")).ok()?,
        key_der: std::fs::read(p("key.der")).ok()?,
    };
    let _ = std::fs::remove_dir_all(&dir);
    Some(cert)
}

/// TLS listener on a free port serving `fake`. Returns the port.
async fn start_tls_fake(fake: FakeRedis, cert: &Cert) -> u16 {
    let config = ServerConfig::builder_with_provider(Arc::new(ring::default_provider()))
        .with_safe_default_protocol_versions()
        .unwrap()
        .with_no_client_auth()
        .with_single_cert(
            vec![CertificateDer::from(cert.cert_der.clone())],
            PrivateKeyDer::from(PrivatePkcs8KeyDer::from(cert.key_der.clone())),
        )
        .unwrap();
    let acceptor = TlsAcceptor::from(Arc::new(config));
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    tokio::spawn(async move {
        loop {
            let Ok((sock, _)) = listener.accept().await else {
                return;
            };
            let (acceptor, fake) = (acceptor.clone(), fake.clone());
            tokio::spawn(async move {
                if let Ok(stream) = acceptor.accept(sock.compat()).await {
                    fake.serve_stream(stream).await;
                }
            });
        }
    });
    port
}

fn cfg(addr: String, roots: Vec<Vec<u8>>) -> RedisConfig {
    RedisConfig {
        addr,
        tls: true,
        tls_extra_roots_der: roots,
        command_timeout: Duration::from_secs(5),
        connect_timeout: Duration::from_secs(5),
        ..RedisConfig::default()
    }
}

#[tokio::test]
async fn conformance_over_tls() {
    let Some(cert) = generate_cert() else {
        eprintln!("NOTICE: openssl CLI unavailable or failed, skipping TLS test");
        return;
    };
    let port = start_tls_fake(FakeRedis::with_password(None, "tok"), &cert).await;
    let kv = RedisKv::new(
        TokioProviders::new(),
        RedisConfig {
            password: Some("tok".into()),
            ..cfg(format!("localhost:{port}"), vec![cert.cert_der.clone()])
        },
    );
    kv.ping().await.expect("TLS ping with AUTH");
    conformance(&kv).await.expect("conformance over TLS");

    // The same through a rediss:// URL (the token form), trusting our root.
    let mut c = RedisConfig::from_url(&format!("rediss://:tok@localhost:{port}")).unwrap();
    c.tls_extra_roots_der = vec![cert.cert_der.clone()];
    assert!(c.tls);
    RedisKv::new(TokioProviders::new(), c).ping().await.expect("rediss url");
}

#[tokio::test]
async fn untrusted_or_mismatched_certificates_are_refused() {
    let Some(cert) = generate_cert() else {
        eprintln!("NOTICE: openssl CLI unavailable or failed, skipping TLS test");
        return;
    };
    let port = start_tls_fake(FakeRedis::new(), &cert).await;

    // Unknown issuer: not in the web PKI roots and not added.
    let kv = RedisKv::new(TokioProviders::new(), cfg(format!("localhost:{port}"), vec![]));
    let err = kv.ping().await.unwrap_err();
    assert!(
        matches!(&err, KvError::Unavailable(m) if m.contains("TLS handshake")),
        "{err:?}"
    );

    // Trusted issuer but wrong host name (certificate is for localhost).
    let kv = RedisKv::new(
        TokioProviders::new(),
        cfg(format!("127.0.0.1:{port}"), vec![cert.cert_der.clone()]),
    );
    let err = kv.ping().await.unwrap_err();
    assert!(
        matches!(&err, KvError::Unavailable(m) if m.contains("TLS handshake")),
        "{err:?}"
    );

    // A plaintext client against the TLS port never gets a PONG.
    let plain = RedisKv::new(
        TokioProviders::new(),
        RedisConfig {
            tls: false,
            command_timeout: Duration::from_millis(500),
            ..cfg(format!("localhost:{port}"), vec![])
        },
    );
    assert!(plain.ping().await.is_err());
}
